# Catálogos técnicos; los resultados detallados solo pertenecen al bundle privado.
QUERIES = {
'extensions': "select extname,extversion,n.nspname schema from pg_extension e join pg_namespace n on n.oid=e.extnamespace order by extname",
'schemas': "select nspname,pg_get_userbyid(nspowner) owner,nspacl::text acl from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema' order by nspname",
'relations': "select n.nspname schema,c.relname name,c.relkind,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner) owner from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_' and n.nspname<>'information_schema' and c.relkind in ('r','p','v','m','S') order by 1,2",
'columns': "select n.nspname schema,c.relname name,a.attname,a.attnum,format_type(a.atttypid,a.atttypmod) type,a.attnotnull,a.attidentity,a.attgenerated,pg_get_expr(d.adbin,d.adrelid) default_expr from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname !~ '^pg_' and n.nspname<>'information_schema' and c.relkind in ('r','p','v','m','S') and a.attnum>0 and not a.attisdropped order by 1,2,a.attnum",
'policies': "select schemaname,tablename,policyname,permissive,roles,cmd,qual,with_check from pg_policies where schemaname !~ '^pg_' order by schemaname,tablename,policyname",
'constraints': "select n.nspname schema,c.relname name,k.conname,k.contype,k.convalidated,pg_get_constraintdef(k.oid,true) definition from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_' and n.nspname<>'information_schema' order by 1,2,3",
'indexes': "select schemaname,tablename,indexname,indexdef from pg_indexes where schemaname !~ '^pg_' and schemaname<>'information_schema' order by schemaname,tablename,indexname",
'functions': "select n.nspname schema,p.proname,p.oid::regprocedure::text signature,pg_get_userbyid(p.proowner) owner,p.prosecdef,p.proconfig,p.proacl::text acl,pg_get_functiondef(p.oid) definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname !~ '^pg_' and n.nspname<>'information_schema' and p.prokind in ('f','p','w') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e') order by 1,3",
 'triggers': "select n.nspname schema,c.relname name,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,true) definition from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname !~ '^pg_' and n.nspname<>'information_schema' order by 1,2,3",
'roles': "select rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls,rolconnlimit,rolconfig from pg_roles where rolname !~ '^pg_' order by rolname",
'memberships': "select r.rolname role,m.rolname member,g.rolname grantor,a.admin_option,a.inherit_option,a.set_option from pg_auth_members a join pg_roles r on r.oid=a.roleid join pg_roles m on m.oid=a.member join pg_roles g on g.oid=a.grantor order by 1,2,3",
'sequences': "select schemaname,sequencename,sequenceowner,data_type,start_value,min_value,max_value,increment_by,cycle,cache_size from pg_sequences where schemaname !~ '^pg_' order by schemaname,sequencename",
'default_acl': "select pg_get_userbyid(d.defaclrole) role,n.nspname schema,d.defaclobjtype,d.defaclacl::text acl from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace order by 1,2,3",
'relation_acl': "select n.nspname schema,c.relname name,pg_get_userbyid(a.grantor) grantor,case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end grantee,a.privilege_type,a.is_grantable from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(c.relacl) a where n.nspname !~ '^pg_' and n.nspname<>'information_schema' order by 1,2,3,4,5",
'column_acl': "select n.nspname schema,c.relname name,t.attname,pg_get_userbyid(a.grantor) grantor,case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end grantee,a.privilege_type,a.is_grantable from pg_attribute t join pg_class c on c.oid=t.attrelid join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(t.attacl) a where n.nspname !~ '^pg_' and n.nspname<>'information_schema' order by 1,2,3,4,5,6",
'views': "select n.nspname schema,c.relname name,pg_get_viewdef(c.oid,true) definition from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_' and n.nspname<>'information_schema' and c.relkind in ('v','m') order by 1,2",
'migrations': "select version,name from supabase_migrations.schema_migrations order by version"
}
def ident(s):return '"'+s.replace('"','""')+'"'
def wrapped(query):return "select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from ("+query+") x;"
def fingerprint(schema,table):
 return "select json_build_object('count',count(*),'md5',md5(coalesce(string_agg(j::text,E'\\n' order by j::text),''))) from (select to_jsonb(t) j from "+ident(schema)+'.'+ident(table)+" t) x;"
